typedef unsigned int u_int;
typedef unsigned long long u_long;
typedef unsigned int u_long128 __attribute__((mode(TI)));

#define TRUE 1
#define TS_NONE (-1)
#define UNCMASK 0x0fffffff
#define VIBUF_ELM_SIZE 2048
#define DMA_ID_NEXT 2
#define DMA_ID_REF 3
#define D4_MADR ((volatile u_int*)0x1000a010)
#define D4_QWC ((volatile u_int*)0x1000a020)
#define D4_TADR ((volatile u_int*)0x1000a030)

typedef union {
    u_long l[2];
    u_int ui[4];
} QWORD;

typedef struct {
    long pts;
    long dts;
    int pos;
    int len;
} TimeStamp;

typedef struct {
    u_int words[9];
} sceIpuDmaEnv;

typedef struct {
    u_long128 *data;
    u_long128 *tag;
    int n;
    int dmaStart;
    int dmaN;
    int readBytes;
    int buffSize;
    sceIpuDmaEnv env;
    int sema;
    int isActive;
    long totalBytes;
    TimeStamp *ts;
    int n_ts;
    int count_ts;
    int wt_ts;
} ViBuf;

static inline void *DmaAddr(void *val)
{
    return (void*)((unsigned)val & UNCMASK);
}

static void scTag2(QWORD*, void*, u_int, u_int);
static void setD4_CHCR(u_int);

int viBufReset(ViBuf* f)
{
    int i;

    f->dmaStart = 0;
    f->dmaN = 0;
    f->readBytes = 0;
    f->isActive = TRUE;
    f->count_ts = 0;
    f->wt_ts = 0;
    for( i = 0; i < f->n_ts; i++ )
    {
        f->ts[i].pts = TS_NONE;
        f->ts[i].dts = TS_NONE;
        f->ts[i].pos = 0;
        f->ts[i].len = 0;
    }
    for( i = 0; i < f->n; i++ )
    {
        scTag2( (QWORD*)(f->tag + i), DmaAddr((char*)f->data + VIBUF_ELM_SIZE * i), DMA_ID_REF, VIBUF_ELM_SIZE / 16 );
    }
    scTag2( (QWORD*)(f->tag + i), DmaAddr(f->tag), DMA_ID_NEXT, 0 );

    *D4_QWC = 0;
    *D4_MADR = (u_int)DmaAddr( f->data );
    *D4_TADR = (u_int)DmaAddr( f->tag );
    setD4_CHCR( (0 << 8) | (1 << 2) | 1 );

    return TRUE;
}
